import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const p=JSON.parse('{"title":"Stablecoins and USDC: A Primer","description":"","frontmatter":{},"headers":[],"relativePath":"learn/02-agent-payments/stablecoins-and-usdc.md","filePath":"learn/02-agent-payments/stablecoins-and-usdc.md","lastUpdated":1792595354000}'),i={name:"learn/02-agent-payments/stablecoins-and-usdc.md"};function r(o,e,l,d,c,u){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="stablecoins-and-usdc-a-primer" tabindex="-1">Stablecoins and USDC: A Primer <a class="header-anchor" href="#stablecoins-and-usdc-a-primer" aria-label="Permalink to &quot;Stablecoins and USDC: A Primer&quot;">​</a></h1><p>A stablecoin is a digital token designed to track the value of an asset, commonly the US dollar. It can provide a familiar unit of account for on-chain payments, but stability is a design goal rather than a mathematical guarantee. Issuer, reserve, operational, regulatory, and blockchain risks remain.</p><h2 id="why-use-a-stable-value-asset" tabindex="-1">Why use a stable-value asset? <a class="header-anchor" href="#why-use-a-stable-value-asset" aria-label="Permalink to &quot;Why use a stable-value asset?&quot;">​</a></h2><p>If an API is priced in a volatile token, the dollar cost of a call can change quickly, making budgets and pricing harder to reason about. A dollar-linked token gives buyers and providers a more predictable denomination. Stablecoins can also be transferred by software and used across borders without the same account setup as many traditional payment services.</p><p>These properties can be useful for frequent, small machine payments. They do not eliminate the need for wallet security, recipient verification, policy enforcement, or settlement monitoring.</p><h2 id="why-usdc-in-this-learning-material" tabindex="-1">Why USDC in this learning material? <a class="header-anchor" href="#why-usdc-in-this-learning-material" aria-label="Permalink to &quot;Why USDC in this learning material?&quot;">​</a></h2><p>USDC is a widely used dollar-denominated stablecoin. On supported EVM networks, its implementation of EIP-3009 can allow a holder to sign an authorization that another party submits, so the buyer does not necessarily need to hold the network&#39;s gas token. See <a href="./gasless-eip-3009">Gasless Authorization</a>.</p><p>Support depends on the specific token deployment and network. Verify contract addresses and current network support using authoritative project documentation; do not assume every token or chain supports the same behavior. AgentPay examples should use testnets and test tokens, not production funds.</p><h2 id="use-integer-base-units" tabindex="-1">Use integer base units <a class="header-anchor" href="#use-integer-base-units" aria-label="Permalink to &quot;Use integer base units&quot;">​</a></h2><p>USDC commonly uses six decimal places. Applications should represent amounts as integers in base units rather than binary floating-point values:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Display amount</th><th style="text-align:right;">Base units</th></tr></thead><tbody><tr><td style="text-align:right;">1 USDC</td><td style="text-align:right;">1,000,000</td></tr><tr><td style="text-align:right;">0.1 USDC</td><td style="text-align:right;">100,000</td></tr><tr><td style="text-align:right;">0.000001 USDC</td><td style="text-align:right;">1</td></tr></tbody></table><p>Floating-point calculations can introduce rounding errors. Parse and validate decimal input, convert it to integer units, and keep it integer-valued through policy checks and payment construction.</p>',12)])])}const m=t(i,[["render",r]]);export{p as __pageData,m as default};
